window.addEventListener("load",function(){const myPage="Accueil";const sousTitre=document.getElementById("soustitre");sousTitre.innerHTML=myPage;const xhttp=new XMLHttpRequest();xhttp.onload=function(){document.getElementsByTagName("section")[0].innerHTML=this.responseText;initializeViewer();};xhttp.onerror=function(){let errorString="Page introuvable";document.getElementsByTagName("section")[0].innerHTML=errorString;};xhttp.open("GET","./php/routage.php?page=" + encodeURIComponent(myPage));xhttp.send();});function loadPage(element,event){event.preventDefault();const myPage=element.innerHTML;clearInterval(myTimerInterval);const sousTitre=document.getElementById("soustitre");sousTitre.innerHTML=myPage;const xhttp=new XMLHttpRequest();xhttp.onload=function(){document.getElementsByTagName("section")[0].innerHTML=this.responseText;if(myPage==="Accueil"){initializeViewer();}};xhttp.onerror=function(){let errorString="Page introuvable";document.getElementsByTagName("section")[0].innerHTML=errorString;};xhttp.open("GET","./php/routage.php?page=" + encodeURIComponent(myPage));xhttp.send();}function initializeViewer(){const containerViewer=document.getElementById("viewer");if(!containerViewer){return;}loadImg("./viewer/imgViewer.xml",containerViewer,function(){if(!containerViewer.isConnected){return;}clearInterval(myTimerInterval);myTimerInterval=setInterval(myTimerScrollImg,timeScrolling);});}
